CREATE SCHEMA auth; CREATE SCHEMA account_private;
CREATE ROLE authenticated; CREATE ROLE anon;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE FUNCTION public.admin_operator() RETURNS boolean LANGUAGE sql AS $$select coalesce(auth.uid()='00000000-0000-4000-8000-000000000001'::uuid,false)$$;
CREATE FUNCTION account_private.allowed(uuid) RETURNS boolean LANGUAGE sql AS $$select $1 is not null and $1 <> '00000000-0000-4000-8000-000000000099'::uuid$$;
CREATE TABLE profiles(id uuid primary key,display_name text,neis_office_code text,neis_school_code text,academic_status text,grade_level int);
CREATE TABLE universities(id uuid primary key,name text);
CREATE TABLE content_items(id uuid primary key,title text);
CREATE TABLE student_target_universities(id uuid,user_id uuid,university_id uuid,admission_year int,status text,created_at timestamptz);
CREATE TABLE bookmarks(id uuid,user_id uuid,content_item_id uuid,created_at timestamptz);
CREATE TABLE recent_views(id uuid,user_id uuid,content_item_id uuid,viewed_at timestamptz);
CREATE TABLE student_applications(id uuid,user_id uuid,university_id uuid,admission_year int,intended_division text,admission_type text,admission_name text,created_at timestamptz);
CREATE TABLE student_application_events(id uuid,application_id uuid,kind text,supersedes_event_id uuid,occurred_at timestamptz,recorded_at timestamptz);
CREATE TABLE study_sessions(user_id uuid,started_at timestamptz,ended_at timestamptz,include_in_study_total boolean,active_segments jsonb);
